--
-- Table structure for table `absensi_detail`
--

DROP TABLE IF EXISTS `absensi_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `absensi_detail` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `absensi_id` int(11) unsigned NOT NULL,
  `siswa_id` int(11) unsigned NOT NULL,
  `status` enum('hadir','izin','sakit','alpa') NOT NULL DEFAULT 'alpa',
  `keterangan` text DEFAULT NULL,
  `waktu_absen` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `absensi_id_siswa_id` (`absensi_id`,`siswa_id`),
  KEY `absensi_detail_siswa_id_foreign` (`siswa_id`),
  CONSTRAINT `absensi_detail_absensi_id_foreign` FOREIGN KEY (`absensi_id`) REFERENCES `absensi` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `absensi_detail_siswa_id_foreign` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

