DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `role` enum('admin','guru_mapel','wali_kelas','wakakur','siswa') DEFAULT 'siswa',
  `email` varchar(100) DEFAULT NULL,
  `profile_photo` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT NULL,
  `password_changed_at` datetime DEFAULT NULL COMMENT 'Timestamp when password was last changed by user',
  `email_changed_at` datetime DEFAULT NULL COMMENT 'Timestamp when email was last set/changed by user',
  `profile_photo_uploaded_at` datetime DEFAULT NULL COMMENT 'Timestamp when profile photo was uploaded',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=1160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

